//
//  ANGReaderTests.swift
//  Moved from Electron Microscopy Studio's EMStudioTests (at 67d6df4) by FormatoKit#147, with its fixtures and truths unchanged.
//  The .ang reader against orix 0.15.0 (`ang.file_reader`): every Fixtures/ebsd-*.ang reads with the values of
//  Fixtures/ebsd-edax.truth.json (tools/ebsd-readers/make_edax_fixtures.py): vendor and column names, the header's grid, step and
//  projection centre, the map shape and step as orix's CrystalMap derives them from the columns, the phase list (ids, autogenerated
//  names, point groups after orix's EDAX aliases, lattices), every column bit-equal through its sha256 (phase_id after the not-indexed
//  convention), the first and last row. The rotations (`eu2qu` of these Euler columns) are DiffractoKit's and its own parity's; the
//  Euler columns they are made from are held bit for bit here.
//

import Foundation
import XCTest
@testable import FormatoEBSD

nonisolated final class ANGReaderTests: XCTestCase {

    nonisolated struct Truth: Decodable {
        let fileSHA256: String
        let vendor: String
        let columns: [String]
        let nRows: Int
        let nColumns: Int
        let headerFields: [String: String]
        let shape: [Int]
        let dx: String
        let dy: String
        let scanUnit: String
        let phaseIDs: [Int]
        let phaseNames: [String]
        let pointGroups: [String?]
        let lattices: [[String]]
        let columnSHA256: [String: String]
        let firstRow: [String]
        let lastRow: [String]
        let phaseIDCounts: [String: Int]
        let notIndexed: Int
        let propNames: [String]
        enum CodingKeys: String, CodingKey {
            case vendor, columns, shape, dx, dy, lattices
            case fileSHA256 = "file_sha256", nRows = "n_rows", nColumns = "n_columns", headerFields = "header_fields", scanUnit = "scan_unit"
            case phaseIDs = "phase_ids", phaseNames = "phase_names", pointGroups = "point_groups", columnSHA256 = "column_sha256"
            case firstRow = "first_row", lastRow = "last_row", phaseIDCounts = "phase_id_counts", notIndexed = "not_indexed"
            case propNames = "prop_names"
        }
    }

    nonisolated struct TruthFile: Decodable {
        let orix: String
        let ang: [String: Truth]
    }

    static func truth() throws -> TruthFile {
        try JSONDecoder().decode(TruthFile.self, from: Data(contentsOf: EBSDFixtures.url("ebsd-edax.truth.json")))
    }

    private func double(_ text: String, _ what: String) throws -> Double {
        try XCTUnwrap(Double(text), "\(what): '\(text)' is not a number")
    }

    private func assertClose(_ value: Double, _ text: String, _ what: String, file: StaticString = #filePath, line: UInt = #line) throws {
        let expected = try double(text, what)
        XCTAssertEqual(value, expected, accuracy: max(1e-12 * abs(expected), 1e-12), what, file: file, line: line)
    }

    private func bytes(_ values: [Double]) -> Data {
        var out = Data(capacity: values.count * 8)
        for value in values { withUnsafeBytes(of: value.bitPattern.littleEndian) { out.append(contentsOf: $0) } }
        return out
    }

    private func column(_ name: String, of file: ANGMap) -> [Double]? {
        let map = file.map
        switch name {
        case "euler1": return map.euler.map(\.x)
        case "euler2": return map.euler.map(\.y)
        case "euler3": return map.euler.map(\.z)
        case "x": return map.x
        case "y": return map.y
        case "phase_id": return map.phaseIDs?.map(Double.init)
        default: return map.properties[name]
        }
    }

    func testTruthIsOrix0150() throws {
        let truth = try Self.truth()
        XCTAssertEqual(truth.orix, "0.15.0")
        XCTAssertEqual(Set(truth.ang.keys), ["ebsd-sdss-ferrite-austenite.ang", "ebsd-tsl.ang", "ebsd-tsl-hex.ang"])
    }

    func testEveryFixtureReadsAsOrixReadsIt() throws {
        for (name, expected) in try Self.truth().ang {
            let url = EBSDFixtures.url(name)
            XCTAssertEqual(EBSDFixtures.sha256(try Data(contentsOf: url)), expected.fileSHA256, "\(name): the fixture is not the one the truth was written from")
            let map = try ANGReader.read(url: url)
            XCTAssertEqual(map.vendor.rawValue, expected.vendor, "\(name) vendor")
            XCTAssertEqual(map.columnNames, expected.columns, "\(name) columns")
            XCTAssertEqual(map.pointCount, expected.nRows, "\(name) rows")
            XCTAssertEqual(map.columnNames.count, expected.nColumns, "\(name) column count")
            XCTAssertEqual(map.map.euler.count, expected.nRows, name)
            XCTAssertEqual(map.map.phaseIDs?.count, expected.nRows, name)
            // The header fields orix leaves in the file.
            XCTAssertEqual(map.header.grid, expected.headerFields["GRID"], "\(name) grid")
            func field(_ key: String) throws -> String { try XCTUnwrap(expected.headerFields[key], "\(name): no \(key) in the truth") }
            let stepX = try XCTUnwrap(map.header.stepX), stepY = try XCTUnwrap(map.header.stepY)
            try assertClose(stepX, try field("XSTEP"), "\(name) XSTEP")
            try assertClose(stepY, try field("YSTEP"), "\(name) YSTEP")
            let columnsOdd = Int(try field("NCOLS_ODD")), columnsEven = Int(try field("NCOLS_EVEN")), rows = Int(try field("NROWS"))
            XCTAssertEqual(map.header.columnsOdd, columnsOdd, "\(name) NCOLS_ODD")
            XCTAssertEqual(map.header.columnsEven, columnsEven, "\(name) NCOLS_EVEN")
            XCTAssertEqual(map.header.rows, rows, "\(name) NROWS")
            let pc = try XCTUnwrap(map.header.projectionCenter, "\(name) projection centre")
            try assertClose(pc.x, try field("x-star"), "\(name) x-star")
            try assertClose(pc.y, try field("y-star"), "\(name) y-star")
            try assertClose(pc.z, try field("z-star"), "\(name) z-star")
            let workingDistance = try XCTUnwrap(map.header.workingDistance), pixelsPerMicron = try XCTUnwrap(map.header.temPixelsPerMicron)
            try assertClose(workingDistance, try field("WorkingDistance"), "\(name) working distance")
            try assertClose(pixelsPerMicron, try field("TEM_PIXperUM"), "\(name) TEM_PIXperUM")
            XCTAssertEqual(map.header.lines.count, map.header.lines.filter { $0.hasPrefix("#") }.count, "\(name): header lines start with #")
            // The map as orix's CrystalMap derives it from the columns.
            let orix = OrixView(map.map)
            XCTAssertEqual(try orix.shape(), expected.shape, "\(name) shape")
            try assertClose(orix.dx, expected.dx, "\(name) dx")
            try assertClose(orix.dy, expected.dy, "\(name) dy")
            XCTAssertEqual(map.map.scanUnit, expected.scanUnit, "\(name) scan unit")
            XCTAssertEqual(orix.phaseList, expected.phaseIDs, "\(name) phase ids")
            // The file's phases: orix's list without the not-indexed phase it adds for −1.
            let named = expected.phaseIDs.indices.filter { expected.phaseIDs[$0] != -1 }
            XCTAssertEqual(orix.phases.map(\.name), named.map { expected.phaseNames[$0] }, "\(name) phase names")
            XCTAssertEqual(orix.phases.map(\.pointGroup), named.map { expected.pointGroups[$0] }, "\(name) point groups")
            XCTAssertEqual(orix.phases.count, named.count, "\(name) lattices")
            for (phase, k) in zip(orix.phases, named) {
                let ours = phase.lattice ?? []
                XCTAssertEqual(ours.count, expected.lattices[k].count, "\(name) \(phase.name) lattice")
                for (value, text) in zip(ours, expected.lattices[k]) { try assertClose(value, text, "\(name) \(phase.name) lattice") }
                XCTAssertEqual(phase.latticeUnit, EBSDPhaseHeader.angstrom, "\(name) \(phase.name) lattice unit")
            }
            for (columnName, sha) in expected.columnSHA256 {
                let values = try XCTUnwrap(column(columnName, of: map), "\(name): no column \(columnName)")
                XCTAssertEqual(EBSDFixtures.sha256(bytes(values)), sha, "\(name) column \(columnName), bit for bit")
            }
            XCTAssertEqual(Set(map.map.properties.keys), Set(expected.propNames), "\(name) properties")
            let first = try map.columnNames.map { try XCTUnwrap(column($0, of: map))[0] }
            let last = try map.columnNames.map { try XCTUnwrap(column($0, of: map))[map.pointCount - 1] }
            // The first and last row as written (phase_id as written: orix's -1 is checked through the column sha and the counts).
            for (i, columnName) in map.columnNames.enumerated() where columnName != "phase_id" {
                try assertClose(first[i], expected.firstRow[i], "\(name) first row \(columnName)")
                try assertClose(last[i], expected.lastRow[i], "\(name) last row \(columnName)")
            }
            var counts: [String: Int] = [:]
            for id in orix.phaseIDs { counts[String(id), default: 0] += 1 }
            XCTAssertEqual(counts, expected.phaseIDCounts, "\(name) phase id counts")
            XCTAssertEqual(map.notIndexedCount, expected.notIndexed, "\(name) not indexed")
        }
    }

    func testHeaderParsingFollowsOrixsRegularExpressions() throws {
        // Names and formulas are read after one or more blanks; a header without Phase lines numbers the phases from 0; an unknown
        // symmetry is refused.
        let text = """
        # MaterialName  \tAlpha Beta
        # Formula   AB
        # Symmetry  62
        # LatticeConstants  2.95 2.95 4.68 90 90 120
        # GRID: SqrGrid
        0.1 0.2 0.3 0 0 10 0.5 0 100 0.1
        0.1 0.2 0.3 1 0 10 -1 0 100 0.1
        """
        let map = try ANGReader.read(text: text, url: URL(fileURLWithPath: "/tmp/a.ang"))
        XCTAssertEqual(map.vendor, .tsl)
        let orix = OrixView(map.map)
        XCTAssertEqual(orix.phaseList, [-1, 0])
        XCTAssertEqual(map.map.phaseHeaders.map(\.name), ["AB"], "one formula per phase: the name becomes the formula")
        XCTAssertEqual(map.map.phaseHeaders.map(\.pointGroup), ["622"], "orix's alias of EDAX's 62")
        XCTAssertEqual(orix.phase(id: 0)?.lattice, [2.95, 2.95, 4.68, 90, 90, 120])
        XCTAssertEqual(orix.phase(id: 0)?.formula, "AB")
        XCTAssertEqual(map.map.phaseIDs, [0, -1], "confidence index -1 is not indexed")
        XCTAssertEqual(try orix.shape(), [2], "one row of points: y does not vary")
        XCTAssertEqual(orix.dx, 1)
        XCTAssertEqual(orix.dy, 0)
        let noFormula = text.replacingOccurrences(of: "# Formula   AB\n", with: "")
        XCTAssertEqual(try ANGReader.read(text: noFormula, url: URL(fileURLWithPath: "/tmp/b.ang")).map.phaseHeaders.map(\.name), ["Alpha Beta"])
        let unknownSymmetry = text.replacingOccurrences(of: "# Symmetry  62", with: "# Symmetry  99")
        XCTAssertThrowsError(try ANGReader.read(text: unknownSymmetry, url: URL(fileURLWithPath: "/tmp/c.ang"))) { error in
            XCTAssertTrue(((error as? ANGReadError)?.text ?? "").contains("'99'"), String(describing: error))
        }
        let ragged = text + "0.1 0.2\n"
        XCTAssertThrowsError(try ANGReader.read(text: ragged, url: URL(fileURLWithPath: "/tmp/d.ang")))
        XCTAssertThrowsError(try ANGReader.read(text: "# GRID: SqrGrid\n", url: URL(fileURLWithPath: "/tmp/e.ang")))
    }

    /// The data lines as np.loadtxt splits them, read from slices of the text (#713): runs of spaces and tabs, blanks and
    /// non-breaking spaces at the ends, CRLF and CR line ends, blank and comment lines between rows, and the line named in a refusal.
    func testDataLinesSplitOnRunsOfBlanksWhateverTheLineEnds() throws {
        let header = "# MaterialName  Al\r\n# Symmetry  43\r\n# LatticeConstants  4.05 4.05 4.05 90 90 90\r\n# GRID: SqrGrid\r\n"
        let text = header + "  0.1\t 0.2  0.3 0 0 10 0.5 0 100 0.1\u{00A0}\r\n\r\n# a comment\r0.4 0.5 0.6\t\t1 0 10 0.7 0 100 0.2 \r\n"
        let map = try ANGReader.read(text: text, url: URL(fileURLWithPath: "/tmp/f.ang"))
        XCTAssertEqual(map.map.pointCount, 2)
        XCTAssertEqual(map.map.euler.map(\.x), [0.1, 0.4])
        XCTAssertEqual(map.map.euler.map(\.z), [0.3, 0.6])
        XCTAssertEqual(map.map.x, [0, 1])
        XCTAssertEqual(map.map.properties["ci"], [0.5, 0.7])
        XCTAssertEqual(map.map.properties["fit"], [0.1, 0.2])
        let bad = header + "0.1 0.2 0.3 0 0 10 0.5 0 100 0.1\n0.1 x 0.3 0 0 10 0.5 0 100 0.1\n"
        XCTAssertThrowsError(try ANGReader.read(text: bad, url: URL(fileURLWithPath: "/tmp/g.ang"))) { error in
            XCTAssertEqual((error as? ANGReadError)?.text, "g.ang line 6: 'x' is not a number.")
        }
        let ragged = header + "0.1 0.2 0.3 0 0 10 0.5 0 100 0.1\n0.1 0.2\n"
        XCTAssertThrowsError(try ANGReader.read(text: ragged, url: URL(fileURLWithPath: "/tmp/h.ang"))) { error in
            XCTAssertEqual((error as? ANGReadError)?.text, "h.ang line 6 has 2 columns where the first row has 10.")
        }
    }

    func testAnUnexpectedColumnCountFallsBackToOrixsUnknownNames() throws {
        let text = "# Phase 1\n# MaterialName Ni\n# Symmetry 43\n# LatticeConstants 3.5 3.5 3.5 90 90 90\n" +
            "0.1 0.2 0.3 0 0 7 8 1 9 10 11\n0.1 0.2 0.3 1 0 7 8 1 9 10 11\n"
        let map = try ANGReader.read(text: text, url: URL(fileURLWithPath: "/tmp/f.ang"))
        XCTAssertEqual(map.vendor, .unknown, "11 columns match no EDAX variant")
        XCTAssertEqual(map.columnNames, ["euler1", "euler2", "euler3", "x", "y", "unknown1", "unknown2", "phase_id", "unknown3", "unknown4", "unknown5"])
        XCTAssertEqual(map.map.properties["unknown5"], [11, 11])
        XCTAssertEqual(map.map.phaseIDs, [1, 1], "no not-indexed convention for an unknown vendor")
        XCTAssertEqual(OrixView(map.map).phases.map(\.name), ["Ni"], "no formula: the material name stays")
    }

    /// A header phase id that leaves no Int for the phases numbered after it is refused (red before: `Int.max + 1` trapped), and more
    /// than 190 phases sharing a formula and a point group take orix's `chr(65 + i)` on through Unicode (red before: `UInt8(256)`
    /// trapped at the 192nd phase).
    func testHostileHeadersAreRefusedOrNamedAsOrixNamesThem() throws {
        let phase = "# MaterialName A\n# Symmetry 43\n# LatticeConstants 3 3 3 90 90 90\n"
        let rows = "0 0 0 0 0 1 0.5 0 1 0.1\n0 0 0 1 0 1 0.5 0 1 0.1\n"
        let overflowing = "# Phase 9223372036854775807\n" + phase + phase + rows
        XCTAssertThrowsError(try ANGReader.read(text: overflowing, url: URL(fileURLWithPath: "/tmp/g.ang"))) { error in
            XCTAssertTrue(((error as? ANGReadError)?.text ?? "").contains("'9223372036854775807'"), String(describing: error))
        }
        var many = ""
        for _ in 0..<192 { many += "# MaterialName Iron\n# Formula Fe\n# Symmetry 43\n# LatticeConstants 2.87 2.87 2.87 90 90 90\n" }
        let text = many + "0 0 0 0 0 1 0.5 0 1 0.1\n0 0 0 1 0 1 0.5 191 1 0.1\n"
        let orix = OrixView(try ANGReader.read(text: text, url: URL(fileURLWithPath: "/tmp/h.ang")).map)
        XCTAssertEqual(orix.phaseList, [0, 191])
        XCTAssertEqual(orix.phase(id: 0)?.name, "Fe-432-A")
        XCTAssertEqual(orix.phase(id: 191)?.name, "Fe-432-\u{100}", "orix's chr(65 + 191)")
    }
}
